mapper.select:
SELECT * FROM TB_NOTIFICATION 
WHERE MEMBER_ID = #{memberId} 
ORDER BY SENT_AT DESC

mapper.update:
UPDATE TB_NOTIFICATION 
SET READ_YN = 'Y', READ_AT = SYSDATE 
WHERE NOTIFY_ID = #{notifyId}

UPDATE TB_NOTIFY_SETTING 
SET INAPP_YN = #{inappYn}, EMAIL_YN = #{emailYn}, SMS_YN = #{smsYn}, UPDATED_AT = SYSDATE
WHERE MEMBER_ID = #{memberId}
